actions.script:
const answer = ec.resource.script("component://mr-mantle/service/mantle/smithy/Smithy.js").checkRun({repositoryId, pipelineName,
        event, refName, commitId, mergeRequestId, sourceRepositoryId, pushedForReview, triggeredByUserId, trusted, jobCount})
if (answer.decision) {
    decision = answer.decision
    trusted = answer.trusted
    message = answer.message ?? null
    ownerId = answer.ownerId ?? null
    runnerPoolId = answer.runnerPoolId ?? null
}
